{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Resounding Gatherings</title>
  <meta name='description' content='Sound-centric events to reset attention and restabilize the nervous system in {{CITY}}, {{STATE}}.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body>
  <header class='site-header'>
    <div class='wrap'>
      <div class='brand'>
        <h1 class='logo'>{{BUSINESS_NAME}}</h1>
        <p class='tag'>{{TAGLINE}}</p>
      </div>
      <nav class='site-nav' aria-label='Primary'>
        <ul>
          <li><a href='index.html'>Home</a></li>
          <li><a href='events.html'>Gatherings</a></li>
          <li><a href='private-sessions.html'>Private Offerings</a></li>
          <li><a href='pricing.html'>Plans</a></li>
          <li><a href='about.html'>Story</a></li>
          <li><a href='faq.html'>FAQ</a></li>
          <li><a href='book.html' class='primary-cta'>{{PRIMARY_CTA_LABEL}}</a></li>
          <li><a href='contact.html'>Contact</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class='hero'>
      <div class='pattern-bg' aria-hidden='true'></div>
      <div class='wrap hero-inner'>
        <div class='hero-copy'>
          <h2>Enter a tuned space for careful recalibration</h2>
          <p>Join sound gatherings crafted to lift tension and make the edges of your day gentler. Sessions in {{CITY}}, {{STATE}} by donation-based and ticketed options.</p>
          <div class='hero-actions'>
            <a href='events.html' class='btn'>See next gatherings</a>
            <a href='book.html' class='btn btn-outline'>Reserve a private slot</a>
          </div>
          <ul class='meta'>
            <li>Next: <strong id='next-event'>Sun • Mar 7 • 6:30pm</strong></li>
            <li>Questions? Call <a href='tel:{{PHONE}}'>{{PHONE}}</a></li>
          </ul>
        </div>

        <aside class='hero-mixer' aria-labelledby='mixer-heading'>
          <h3 id='mixer-heading'>Prefer how the session lands?</h3>
          <p class='muted'>Choose a sound intensity and get program tips that match.</p>

          <div class='mixer-controls' role='radiogroup' aria-label='Sound intensity'>
            <button class='mixer-btn active' data-level='gentle' aria-pressed='true'>Gentle</button>
            <button class='mixer-btn' data-level='medium' aria-pressed='false'>Medium</button>
            <button class='mixer-btn' data-level='intense' aria-pressed='false'>Intense</button>
          </div>

          <div class='recommendations' id='recommendations'>
            <!-- Filled by JS -->
          </div>

        </aside>
      </div>
    </section>

    <!-- MYTH vs TRUTH -->
    <section class='myth-truth wrap'>
      <h3>Myths that hold people back — and the truth that helps</h3>
      <div class='grid-2'>
        <div class='card'>
          <h4>Myth: Sound baths are one-size-fits-all</h4>
          <p>Truth: We calibrate tone, duration, and pacing so the experience meets your nervous system where it is.</p>
        </div>
        <div class='card'>
          <h4>Myth: You must meditate perfectly</h4>
          <p>Truth: Presence is an invitation, not a requirement. Sessions are adjustable and welcoming to all levels.</p>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class='pillars wrap'>
      <h3>How we shape an hour</h3>
      <div class='grid-3'>
        <div class='pillar'>
          <h4>Intentional Tuning</h4>
          <p>We blend breath-guides and tuned instruments so intention and physiology align.</p>
        </div>
        <div class='pillar'>
          <h4>Dynamic Safety</h4>
          <p>Sound choices support a felt sense of safety while enabling release.</p>
        </div>
        <div class='pillar'>
          <h4>Clear Aftercare</h4>
          <p>Practical, short rituals and guidance help you carry the session forward.</p>
        </div>
      </div>
    </section>

    <!-- CASE NOTES / PROOF GALLERY -->
    <section class='case-notes wrap' aria-labelledby='proof-heading'>
      <h3 id='proof-heading'>Proof Gallery</h3>
      <p class='muted'>Peer feedback and neighborhood credentials—rotate through real notes and organizational markers.</p>

      <div class='proof-grid'>
        <div class='testimonials' id='testimonials' aria-live='polite'>
          <!-- Rotating testimonials from JS -->
        </div>

        <div class='badges' id='badges'>
          <!-- Credibility badges with tooltips -->
          <button class='badge' data-tip='Certified facilitator training, 2019'>FAC-2019</button>
          <button class='badge' data-tip='Community grant recipient, 2022'>GRANT</button>
          <button class='badge' data-tip='Partner venue: Meridian Wellness'>MERIDIAN</button>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class='faq wrap'>
      <h3>Common questions</h3>
      <details>
        <summary>What should I bring?</summary>
        <p>Comfortable layers, a mat or blanket, and an open curiosity. We provide bolsters and eye pillows on request.</p>
      </details>
      <details>
        <summary>Is this safe for everyone?</summary>
        <p>Most people can participate safely. Contraindications include recent concussion, uncontrolled seizures, or conditions where loud vibration is contraindicated. Consult your healthcare provider if unsure; reach out to <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a> for specifics.</p>
      </details>
    </section>

    <!-- CTA -->
    <section class='final-cta'>
      <div class='wrap'>
        <h3>Ready to try a session shaped for you?</h3>
        <p>Choose collective gatherings or private sessions. Book a slot and we will help you pick an intensity that feels right.</p>
        <div class='cta-actions'>
          <a href='book.html' class='btn btn-large primary-cta'>{{PRIMARY_CTA_LABEL}}</a>
          <a href='events.html' class='btn btn-outline'>View schedule</a>
        </div>
      </div>
    </section>

  </main>

  <footer class='site-footer'>
    <div class='wrap'>
      <div class='f-left'>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} • <a href='tel:{{PHONE}}'>{{PHONE}}</a>
      </div>
      <div class='f-right'>
        <a href='privacy.html'>Privacy</a> • <a href='contact.html'>Contact</a>
      </div>
    </div>
  </footer>

  <script src='assets/js/main.js' defer></script>
</body>
</html>"} 
