{"path":"assets/css/styles.css","content":"/* Minimal reset */
:root{
  --bg:#0f1720;
  --card:#0b1220;
  --muted:#9aa6b2;
  --accent:#8be0c7;
  --glass: rgba(255,255,255,0.04);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;line-height:1.4;color:#e6eef3;background:linear-gradient(180deg,var(--bg),#081018);}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);border-bottom:1px solid rgba(255,255,255,0.03)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand .logo{margin:0;font-size:1.1rem}
.brand .tag{margin:0;color:var(--muted);font-size:0.86rem}
.site-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px;align-items:center}
.site-nav a{color:#dff3ef;text-decoration:none;font-size:0.95rem;padding:8px 10px;border-radius:6px}
.site-nav a.primary-cta{background:var(--accent);color:#05201a}
.hero{position:relative;padding:48px 0}
.pattern-bg{position:absolute;inset:0;opacity:0.06;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;mix-blend-mode:screen}
.hero-inner{display:flex;gap:28px;align-items:flex-start}
.hero-copy{flex:1;color:#eaf8f2}
.hero-copy h2{margin-top:0;font-size:1.8rem}
.hero-actions{margin:18px 0;display:flex;gap:12px}
.btn{display:inline-block;padding:10px 14px;background:#072022;color:#dff3ef;text-decoration:none;border-radius:8px;border:1px solid rgba(255,255,255,0.03)}
.btn-outline{background:transparent;border:1px solid rgba(255,255,255,0.06)}
.btn-large{padding:14px 20px}
.primary-cta{background:var(--accent);color:#05201a}
.meta{list-style:none;padding:0;margin:12px 0 0 0;color:var(--muted);display:flex;gap:12px}
.hero-mixer{width:320px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.mixer-controls{display:flex;gap:8px;margin:8px 0}
.mixer-btn{flex:1;padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#d8f7ee;cursor:pointer}
.mixer-btn.active{background:var(--accent);color:#04211b}
.recommendations{margin-top:12px}
.rec-card{background:var(--glass);padding:10px;border-radius:8px;margin-bottom:8px;color:#cfeee6}
.myth-truth,.pillars,.case-notes,.faq{padding:36px 0;color:#e7f6f0}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.card{background:rgba(255,255,255,0.02);padding:16px;border-radius:10px}
.pillar{background:rgba(255,255,255,0.02);padding:16px;border-radius:10px}
.case-notes .proof-grid{display:flex;gap:18px;align-items:flex-start}
.testimonials{flex:2;background:rgba(255,255,255,0.02);padding:18px;border-radius:10px;min-height:120px}
.testimonial{font-style:italic;color:#dbf3eb}
.test-author{margin-top:12px;color:var(--muted);font-size:0.9rem}
.badges{flex:1;display:flex;flex-direction:column;gap:8px;align-items:flex-start}
.badge{background:#072c28;color:#bff3e8;padding:8px 10px;border-radius:8px;border:none;cursor:default}
.tooltip{position:fixed;background:#042229;color:#d7fff5;padding:8px 10px;border-radius:6px;box-shadow:0 6px 20px rgba(0,0,0,0.5);font-size:0.85rem;display:none}
.faq details{background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;margin-top:8px}
.final-cta{background:linear-gradient(90deg,rgba(139,224,199,0.06),transparent);padding:28px 0;margin-top:18px}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);color:var(--muted);padding:18px 0}
.f-right a{color:var(--muted);text-decoration:none}
@media(max-width:900px){
  .hero-inner{flex-direction:column}
  .grid-3,.grid-2{grid-template-columns:1fr}
  .hero-mixer{width:100%}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mixer: swap recommendations depending on selected intensity
  const recs = {
    gentle: [
      {title: 'Restorative Drift', desc: 'Long tones, soft breath cues, 45 minutes — ideal for deep unwinding.'},
      {title: 'Evening Ease', desc: 'Shorter laying-in sequence with warm overtones.'}
    ],
    medium: [
      {title: 'Balance Session', desc: 'Moderate resonance with pacing to open circulation and calm the mind.'},
      {title: 'Community Flow', desc: 'Shared space with guided pauses and layered instruments.'}
    ],
    intense: [
      {title: 'Release Wave', desc: 'Higher dynamic range, rhythmic anchors to assist strong release.'},
      {title: 'Deep Tuning', desc: 'Extended harmonic series for embodied reckonings.'}
    ]
  };

  function renderRecommendations(level){
    const container = document.getElementById('recommendations');
    container.innerHTML = '';
    (recs[level] || []).forEach(r => {
      const el = document.createElement('div');
      el.className = 'rec-card';
      el.innerHTML = "<strong>"+r.title+"</strong><div class='muted'>"+r.desc+"</div>";
      container.appendChild(el);
    });
  }

  document.addEventListener('DOMContentLoaded', function(){
    // Setup mixer buttons
    const buttons = Array.from(document.querySelectorAll('.mixer-btn'));
    buttons.forEach(btn => {
      btn.addEventListener('click', function(){
        buttons.forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed','false'); });
        btn.classList.add('active'); btn.setAttribute('aria-pressed','true');
        renderRecommendations(btn.dataset.level);
      });
    });
    // initial
    const active = document.querySelector('.mixer-btn.active');
    renderRecommendations(active ? active.dataset.level : 'gentle');

    // Testimonials rotation + badges tooltip
    const testimonials = [
      {text: 'Leaving here felt like settling into a chair I did not know I owned.', author: '— L.M.'},
      {text: 'A rigorous kindness: the sound choices supported me through a hard evening.', author: '— A.R.'},
      {text: 'I slept better for three nights after this session.', author: '— S.K.'}
    ];
    const testContainer = document.getElementById('testimonials');
    let idx = 0;

    function showTest(i){
      testContainer.innerHTML = '';
      const t = document.createElement('div'); t.className='testimonial'; t.textContent = testimonials[i].text;
      const a = document.createElement('div'); a.className='test-author'; a.textContent = testimonials[i].author;
      testContainer.appendChild(t); testContainer.appendChild(a);
    }
    showTest(idx);
    setInterval(()=>{
      idx = (idx+1) % testimonials.length; showTest(idx);
    },4000);

    // Badge tooltips
    const tip = document.createElement('div'); tip.className='tooltip'; document.body.appendChild(tip);
    document.querySelectorAll('.badge').forEach(b => {
      b.addEventListener('mouseenter', e => {
        tip.style.display = 'block'; tip.textContent = b.dataset.tip || '';
        const rect = b.getBoundingClientRect();
        tip.style.left = (rect.right + 10) + 'px';
        tip.style.top = (rect.top) + 'px';
      });
      b.addEventListener('mouseleave', ()=>{ tip.style.display='none'; });
    });

    // Simple next-event logic: update if in the future (placeholder)
    // Could be wired to events page data in future
    const nextEl = document.getElementById('next-event');
    if(nextEl && nextEl.textContent.trim() === ''){ nextEl.textContent = 'No upcoming dates'; }

    // Accessibility: allow keyboard toggling of mixer
    document.querySelectorAll('.mixer-btn').forEach(b=>{
      b.addEventListener('keydown', e=>{
        if(e.key === 'ArrowRight' || e.key === 'ArrowDown'){
          e.preventDefault(); const next = b.nextElementSibling || document.querySelector('.mixer-btn'); next.click(); next.focus();
        }
        if(e.key === 'ArrowLeft' || e.key === 'ArrowUp'){
          e.preventDefault(); const prev = b.previousElementSibling || document.querySelector('.mixer-btn:last-child'); prev.click(); prev.focus();
        }
      });
    });
  });
})();"} 
